behavioralTests:
const label = container.querySelector('[data-test="label"]');
expect(label, 'label present');
expect(label.textContent.trim() === 'on', 'starts at on, got: ' + label.textContent);
container.querySelector('[data-test="set-off"]').click();
await tick();
expect(label.textContent.trim() === 'off', 'after click set-off, got: ' + label.textContent);
container.querySelector('[data-test="set-on"]').click();
await tick();
expect(label.textContent.trim() === 'on', 'after click set-on, got: ' + label.textContent);
